SET ROLE postgres;SELECT set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000001',false);BEGIN;GRANT EXECUTE ON FUNCTION public.previsualizar_correccion_unidad_inicial_sigo(uuid,uuid,text) TO authenticated;GRANT EXECUTE ON FUNCTION public.corregir_unidad_inicial_sigo(uuid,uuid,uuid,text,text,text) TO authenticated;UPDATE sigo_correccion_inicial.configuracion SET habilitada=true;SET ROLE authenticated;DO $$ DECLARE snap text; r jsonb; r2 jsonb; BEGIN SELECT public.previsualizar_correccion_unidad_inicial_sigo('10000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000004','kg')->>'snapshot' INTO snap; r:=public.corregir_unidad_inicial_sigo('10000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000004','70000000-0000-0000-0000-000000000001',snap,'CONFIRMO_CARGA_INICIAL_SIN_MOVIMIENTOS_Y_VALORES_YA_EN_UNIDAD_DESTINO','kg');r2:=public.corregir_unidad_inicial_sigo('10000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000004','70000000-0000-0000-0000-000000000001',snap,'CONFIRMO_CARGA_INICIAL_SIN_MOVIMIENTOS_Y_VALORES_YA_EN_UNIDAD_DESTINO','kg');IF r<>r2 OR r->>'unidad'<>'kg' OR (r->'valores'->>'stock_actual')::numeric<>10 THEN RAISE EXCEPTION 'ASSERT_RECEIPT';END IF;END $$;SET ROLE postgres;DO $$ BEGIN IF (SELECT count(*) FROM sigo_correccion_inicial.auditoria)<>1 OR (SELECT stock_actual FROM productos WHERE id='30000000-0000-0000-0000-000000000004')<>10 OR (SELECT unidad_medida FROM productos WHERE id='30000000-0000-0000-0000-000000000004')<>'kg' THEN RAISE EXCEPTION 'ASSERT_ATOMIC';END IF;END $$;ROLLBACK;
